const layers={rain:{label:'Lluvia',unit:'mm/h',key:'rain',cuts:[0,.2,1,3,8,20],colors:['#cfe8df','#a7ddd4','#57bec6','#258ac0','#4056aa','#71328b']},temperature:{label:'Temperatura',unit:'°C',key:'temperature_2m',cuts:[-10,0,10,20,30,40],colors:['#5665aa','#71b2d5','#80c9ad','#e2d278','#e79558','#ba5053']},wind:{label:'Viento',unit:'km/h',key:'wind_speed_10m',cuts:[0,10,20,40,60,90],colors:['#cee9d9','#8fcbb7','#44a4a1','#4479ae','#7752a3','#a14473']}};
export function weatherColor(kind,value){const s=layers[kind];if(!s||!Number.isFinite(value))return '#9aa7a0';let i=0;for(let n=0;n<s.cuts.length;n++)if(value>=s.cuts[n])i=n;return s.colors[i];}
const desc=c=>!Number.isFinite(c)?'Sin dato de nubosidad':c===0?'Despejado':c<=3?'Parcialmente nublado':c<=48?'Niebla':c<=67?'Lluvia':c<=77?'Nieve':c<=82?'Chubascos':c<=86?'Nieve':'Tormentas';
const symbol=(c,day)=>!Number.isFinite(c)?'—':c===0?(day===0?'☾':day===1?'☀':'○'):c<=3?'☁':c<=48?'≋':c<=67?'☂':c<=86?'❄':'ϟ';
export function initWeather({map,L,esc,date}){
 const $=id=>document.getElementById(id),overlay=L.layerGroup(),selection=L.layerGroup();let active=false,layer='rain',hour=0,data=null,alerts=null,place={name:'Santiago',region:'Región Metropolitana, Chile',latitude:-33.4489,longitude:-70.6693,timezone:'America/Santiago'},version=0,searchVersion=0,play=null,loading=false,alertsLoading=false,forecastError='',alertError='';
 const tools=document.createElement('div');tools.id='weather-tools';tools.hidden=true;tools.innerHTML=`<span class="eyebrow">EXPLORA EL CLIMA</span><h2>Elige una capa</h2><form id="weather-search-form"><label for="weather-search">Buscar ciudad o lugar</label><div class="weather-search-row"><input id="weather-search" type="search" placeholder="Ej. Valparaíso" autocomplete="off" minlength="2" maxlength="100"><button aria-label="Buscar lugar">⌕</button></div></form><p id="weather-search-status" role="status"></p><div id="weather-search-results"></div><div class="weather-layer-buttons">${Object.entries(layers).map(([key,l])=>`<button data-weather-layer="${key}" aria-pressed="${key==='rain'}">${key==='rain'?'☂':key==='wind'?'↗':'◉'} ${l.label}</button>`).join('')}<button data-weather-layer="alerts" aria-pressed="false">⚠ Alertas GDACS</button></div><button id="weather-area">Actualizar área visible</button><button id="weather-refresh">↻ Actualizar datos</button><p class="muted">Selecciona un lugar o pulsa el mapa para consultar su pronóstico.</p><details><summary>Eventos naturales adicionales</summary><p>Consulta sismos y otros eventos en <a href="https://eonet.gsfc.nasa.gov/" target="_blank" rel="noopener noreferrer">NASA EONET</a> y <a href="https://earthquake.usgs.gov/earthquakes/map/" target="_blank" rel="noopener noreferrer">USGS</a>.</p></details>`;
 document.querySelector('.map-catalog').append(tools);
 const panel=document.createElement('div');panel.id='weather-panel';panel.hidden=true;document.querySelector('.map-inspector').append(panel);
 const timeline=document.createElement('div');timeline.id='weather-timeline';timeline.hidden=true;timeline.innerHTML='<button id="weather-play" aria-label="Reproducir pronóstico" aria-pressed="false">▶</button><label for="weather-hour">Hora del pronóstico <strong id="weather-time"></strong></label><input id="weather-hour" type="range" min="0" max="47" value="0"><span id="weather-range"></span>';
 document.querySelector('.map-card').append(timeline);
 const fmt=t=>new Intl.DateTimeFormat('es-CL',{timeZone:place.timezone||'UTC',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(t));
 const n=(v,d=0)=>Number.isFinite(v)?v.toFixed(d):'—';
 const stop=()=>{clearInterval(play);play=null;$('weather-play').textContent='▶';$('weather-play').setAttribute('aria-pressed','false');};
 function draw(){
  if(!active)return;overlay.clearLayers();selection.clearLayers();
  tools.querySelectorAll('[data-weather-layer]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.weatherLayer===layer)));
  timeline.hidden=layer==='alerts';$('weather-area').hidden=layer==='alerts';
  if(layer==='alerts'){drawAlerts();return;}
  const spec=layers[layer];$('map-layer-stamp').textContent=loading?'Consultando pronóstico…':`${spec.label} · pronóstico por horas · ${data?fmt(data.rows[12].hourly.time[hour]*1000):'sin datos'}${data?.stale?' · datos conservados':''}`;
  if(!data){panel.innerHTML=`<h2>Clima por lugar</h2><p role="status">${loading?'<span class="loading-spinner"></span> Preparando pronóstico…':esc(forecastError||'Selecciona un lugar.')}</p>`;$('map-legend').textContent='Open-Meteo · pronóstico, no observación';$('map-coverage').textContent='La fecha y cobertura aparecerán al recibir los datos.';return;}
  for(const r of data.rows){const i=r.hourly.time.indexOf(data.rows[12].hourly.time[hour]),value=r.hourly[spec.key]?.[i];if(!Number.isFinite(value))continue;const color=weatherColor(layer,value),half=data.grid.step/2;
   L.rectangle([[r.latitude-half,r.longitude-half],[r.latitude+half,r.longitude+half]],{color,weight:.5,fillColor:color,fillOpacity:layer==='rain'&&value===0?.06:.34,bubblingMouseEvents:false}).addTo(overlay).bindTooltip(`${spec.label}: ${n(value,layer==='rain'?1:0)} ${spec.unit} · ${fmt(r.hourly.time[i]*1000)}`);
   const wind=layer==='wind'?`<span class="weather-wind-arrow" style="transform:rotate(${Number(r.hourly.wind_direction_10m?.[i]||0)+180}deg)">↑</span>`:'';
   L.marker([r.latitude,r.longitude],{interactive:false,icon:L.divIcon({className:'weather-value',html:`${wind}<b>${n(value,layer==='rain'?1:0)}</b>`,iconSize:[46,28],iconAnchor:[23,14]})}).addTo(overlay);
  }
  L.circleMarker([place.latitude,place.longitude],{radius:8,color:'#005c49',weight:3,fillColor:'#fff',fillOpacity:1}).addTo(selection).bindTooltip(esc(place.name));
  const h=data.rows[12].hourly,t=h.time[hour]*1000;hour=Math.min(hour,h.time.length-1);$('weather-hour').max=h.time.length-1;$('weather-hour').value=hour;$('weather-time').textContent=fmt(t);$('weather-range').textContent='48 h · '+(place.timezone||'UTC');
  $('map-legend').innerHTML=spec.cuts.map((v,i)=>`<span><i style="background:${spec.colors[i]}"></i>${v}</span>`).join('')+` <b>${spec.unit}</b>`;$('count').textContent='25 muestras · cuadrícula aproximada';
  $('map-coverage').innerHTML=`<strong>${esc(spec.label)} · modelo de pronóstico</strong><p><a href="https://open-meteo.com/en/docs" target="_blank" rel="noopener noreferrer">Open-Meteo ↗</a> · CC BY 4.0. Consulta: ${esc(date(data.retrievedAt))}.</p><p>Validez: ${esc(fmt(data.validFrom))} — ${esc(fmt(data.validTo))}. Horas en ${esc(place.timezone||'UTC')}.</p><details><summary>Cobertura y fecha del modelo</summary><p>${esc(data.coverage)} Centro: ${data.grid.center.latitude.toFixed(2)}, ${data.grid.center.longitude.toFixed(2)} · extensión ${data.grid.span.toFixed(1)}°.</p><p>La API no entrega aquí la fecha de emisión de cada modelo. La fecha de consulta no es la emisión.</p></details>${data.stale||forecastError?'<p class="weather-warning">No se pudo renovar la consulta; se conserva el pronóstico fechado anterior.</p>':''}`;
  panel.innerHTML=`<span class="eyebrow">PRONÓSTICO · ${esc(fmt(t))}</span><h2>${esc(place.name)}</h2><p class="muted">${esc(place.region||'Coordenadas seleccionadas')}</p><div class="weather-temperature"><span>${symbol(h.weather_code[hour],h.is_day?.[hour])}</span><strong>${n(h.temperature_2m[hour])}°</strong></div><p>${desc(h.weather_code[hour])} · sensación ${n(h.apparent_temperature[hour])}°</p>${loading?'<p role="status"><span class="loading-spinner"></span> Actualizando lugar…</p>':''}${forecastError?`<p class="weather-warning">${esc(forecastError)}</p>`:''}<div class="weather-metrics"><div>Lluvia<strong>${n(h.rain[hour],1)} mm</strong><small>durante esta hora</small></div><div>Probabilidad<strong>${n(h.precipitation_probability[hour])}%</strong><small>de precipitación</small></div><div>Viento<strong>${n(h.wind_speed_10m[hour])} km/h</strong><small>desde ${n(h.wind_direction_10m[hour])}°</small></div></div><h3>Próximas horas</h3><div class="weather-hourly">${h.time.slice(hour,hour+12).map((v,k)=>{const j=hour+k;return `<button data-weather-hour="${j}" aria-label="Ver ${esc(fmt(v*1000))}"><time>${new Intl.DateTimeFormat('es-CL',{timeZone:place.timezone||'UTC',hour:'2-digit'}).format(v*1000)}</time><span>${symbol(h.weather_code[j],h.is_day?.[j])}</span><b>${n(h.temperature_2m[j])}°</b><small>${n(h.rain[j],1)} mm</small></button>`}).join('')}</div><p class="muted">Desliza para consultar las siguientes horas.</p><button id="weather-show-alerts">Consultar alertas GDACS</button><p class="muted">${esc(data.source)} · consulta ${esc(date(data.retrievedAt))}</p>`;
  panel.querySelectorAll('[data-weather-hour]').forEach(b=>b.onclick=()=>{stop();hour=Number(b.dataset.weatherHour);draw();});$('weather-show-alerts').onclick=()=>setLayer('alerts');
 }
 async function select(next,span=4,move=true){const v=++version;loading=true;forecastError='';stop();draw();try{const u=new URLSearchParams({lat:next.latitude.toFixed(3),lon:next.longitude.toFixed(3),span:String(span)});const r=await fetch('/.netlify/functions/weather?'+u,{signal:AbortSignal.timeout(22000)});if(!r.ok)throw Error();const d=await r.json();if(v!==version)return;if(!d.rows?.[12]?.hourly?.time?.length)throw Error();data=d;place=next;hour=0;if(active&&move)map.setView([place.latitude,place.longitude],7);}catch{if(v===version)forecastError='No se pudo cargar ese lugar. Puedes reintentar; se conserva la consulta anterior.';}finally{if(v===version){loading=false;draw();}}}
 async function loadAlerts(){if(alertsLoading)return;alertsLoading=true;alertError='';draw();try{const r=await fetch('/.netlify/functions/weather?mode=alerts',{signal:AbortSignal.timeout(22000)});if(!r.ok)throw Error();alerts=await r.json();}catch{alertError='No se pudo actualizar GDACS.';}finally{alertsLoading=false;draw();}}
 function drawAlerts(){
  $('map-layer-stamp').textContent='Alertas GDACS · informes de últimos 30 días · cobertura global parcial';$('map-legend').textContent='GDACS: verde / naranja / rojo · impacto humanitario estimado';$('count').textContent=(alerts?.alerts?.length||0)+' eventos en el catálogo';
  const rows=alerts?.alerts||[];for(const a of rows){const color={Green:'#47816a',Orange:'#d48a25',Red:'#be4b4f'}[a.level]||'#68756d';L.circleMarker([a.latitude,a.longitude],{radius:8,color:'#fff',weight:2,fillColor:color,fillOpacity:.9,bubblingMouseEvents:false}).addTo(overlay).bindTooltip(esc(a.title)).on('click',()=>alertDetail(a));}
  $('map-coverage').innerHTML=`<strong>GDACS · Naciones Unidas / Comisión Europea</strong><p>${esc(alerts?.coverage||'Inundaciones, ciclones, sequías e incendios publicados en GDACS.')}</p><p>Publicación del catálogo: ${alerts?.publishedAt?esc(date(alerts.publishedAt)):'pendiente'} · consulta ${alerts?.retrievedAt?esc(date(alerts.retrievedAt)):'pendiente'}.</p><p>Los puntos no delimitan el área afectada. Ausencia de registros no significa ausencia de riesgo.</p><a href="https://www.gdacs.org/" target="_blank" rel="noopener noreferrer">Consultar GDACS ↗</a>${alertError||alerts?.stale?'<p class="weather-warning">No se pudo renovar GDACS. Se conserva el último catálogo disponible con su fecha.</p>':''}`;
  panel.innerHTML=`<span class="eyebrow">ALERTAS Y EVENTOS</span><h2>Catálogo GDACS</h2><p>${alertsLoading?'Consultando alertas…':rows.length+' informes recientes; no equivalen a todos los avisos locales activos.'}</p>${alertError?`<p role="status">${esc(alertError)}</p>`:''}<button id="weather-alert-world">Ver cobertura mundial</button><div class="weather-alert-list">${rows.map((a,i)=>`<button data-alert="${i}"><strong>${esc(({FL:'Inundación',TC:'Ciclón',DR:'Sequía',WF:'Incendio'})[a.type])} · ${esc(a.country||'Sin país indicado')}</strong><small>${esc(a.level)} · ${esc(date(a.updatedAt))}</small></button>`).join('')}</div>`;
  $('weather-alert-world').onclick=()=>map.setView([10,0],2);panel.querySelectorAll('[data-alert]').forEach(b=>b.onclick=()=>{const a=rows[Number(b.dataset.alert)];map.setView([a.latitude,a.longitude],5);alertDetail(a);});
 }
 function alertDetail(a){panel.innerHTML=`<button id="weather-alert-back">← Todas las alertas</button><span class="eyebrow">GDACS · ${esc(a.level)}</span><h2>${esc(a.country||'Sin país indicado')}</h2><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p><p>Inicio: ${esc(date(a.start))}<br>Actualizado por la fuente: ${esc(date(a.updatedAt))}</p><p class="muted">Texto original de GDACS. Punto de referencia, no polígono de afectación.</p><a href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">Ver informe y evolución ↗</a>`;$('weather-alert-back').onclick=draw;if(matchMedia('(max-width:900px)').matches)panel.scrollIntoView({behavior:'smooth',block:'start'});}
 function setLayer(next){const previous=layer;layer=next;stop();if(previous==='alerts'&&next!=='alerts'&&data)map.setView([place.latitude,place.longitude],7);draw();if(next==='alerts'&&!alerts)loadAlerts();}
 tools.querySelectorAll('[data-weather-layer]').forEach(b=>b.onclick=()=>setLayer(b.dataset.weatherLayer));
 $('weather-search-form').onsubmit=async e=>{e.preventDefault();const q=$('weather-search').value.trim(),v=++searchVersion;if(q.length<2)return;$('weather-search-status').textContent='Buscando lugares…';$('weather-search-results').innerHTML='';try{const r=await fetch('/.netlify/functions/weather?mode=search&q='+encodeURIComponent(q),{signal:AbortSignal.timeout(18000)});if(!r.ok)throw Error();const d=await r.json();if(v!==searchVersion)return;$('weather-search-status').textContent=d.places.length?'Elige el lugar correcto:':'No se encontraron lugares.';$('weather-search-results').innerHTML=d.places.map((p,i)=>`<button data-place="${i}"><strong>${esc(p.name)}</strong><small>${esc(p.region)} · ${esc(p.country)}</small></button>`).join('');$('weather-search-results').querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{const p=d.places[Number(b.dataset.place)];setLayer('rain');select({...p,region:[p.region,p.country].filter(Boolean).join(', ')});$('weather-search-results').innerHTML='';$('weather-search-status').textContent='';});}catch{if(v===searchVersion)$('weather-search-status').textContent='No se pudo buscar. Intenta nuevamente.';}};
 $('weather-hour').oninput=e=>{stop();hour=Number(e.target.value);draw();};$('weather-play').onclick=()=>{if(play){stop();return;}if(!data||layer==='alerts')return;$('weather-play').textContent='❚❚';$('weather-play').setAttribute('aria-pressed','true');play=setInterval(()=>{hour=(hour+1)%data.rows[12].hourly.time.length;draw();},1400);};
 $('weather-area').onclick=()=>{const c=map.getCenter(),b=map.getBounds(),span=Math.max(.2,Math.min(12,Math.max(b.getNorth()-b.getSouth(),b.getEast()-b.getWest())));select({name:'Área del mapa',region:`${c.lat.toFixed(3)}, ${c.lng.toFixed(3)}`,latitude:Math.max(-85,Math.min(85,c.lat)),longitude:((c.lng+540)%360)-180,timezone:'UTC'},Math.round(span*100)/100,false);};
 $('weather-refresh').onclick=()=>layer==='alerts'?loadAlerts():select(place,data?.grid.span||4,false);
 map.on('click',e=>{if(active&&layer!=='alerts')select({name:'Punto seleccionado',region:`${e.latlng.lat.toFixed(3)}, ${e.latlng.lng.toFixed(3)}`,latitude:Math.max(-85,Math.min(85,e.latlng.lat)),longitude:((e.latlng.lng+540)%360)-180,timezone:'UTC'});});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
 return {render:draw,setEnabled(value){active=value;document.getElementById('panorama').classList.toggle('weather-active',value);tools.hidden=panel.hidden=timeline.hidden=!value;document.querySelector('#map-catalog-details').hidden=value;$('map-context').hidden=value;document.querySelector('.map-source-status').hidden=value;if(value){overlay.addTo(map);selection.addTo(map);map.invalidateSize();map.setView([place.latitude,place.longitude],7);if(!data&&!loading)select(place);else draw();}else{stop();map.removeLayer(overlay);map.removeLayer(selection);}}};
}
